/* Splitter / linesiter state. Classes are declared `is native`
   with no user fields; the runtime supplies the real layout,
   stack-allocated value type (48 bytes). Both iterators share
   the same struct — linesiter leaves sep NULL. */
typedef struct {
    const char* src;
    uint64_t    src_len;
    const char* sep;
    uint64_t    sep_len;
    uint64_t    cursor;
    bool        done;
} z_t5368_t;

typedef z_t5368_t z_t5444_t;


static z_t5368_t z_t87_split(
    const z_t87_t* self, const z_t87_t* sep);
static z_t5368_t z_t87_split(
    const z_t87_t* self, const z_t87_t* sep) {
    z_t5368_t s;
    s.src = self->data;
    s.src_len = self->size;
    s.sep = sep->data;
    s.sep_len = sep->size;
    s.cursor = 0;
    s.done = (sep->size == 0);
    return s;
}


static z_t5373_t z_t5368_call(z_t5368_t* s);
static z_t5373_t z_t5368_call(z_t5368_t* s) {
    z_t5373_t out = {0};
    if (s->done) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    const char* start = s->src + s->cursor;
    uint64_t remaining = s->src_len - s->cursor;
    if (s->sep_len > remaining) {
        /* no more separators possible — return the tail */
        z_t87_t* boxed = (z_t87_t*)z_xmalloc(sizeof(z_t87_t));
        boxed->data = start;
        boxed->size = remaining;
        s->cursor = s->src_len;
        s->done = true;
        out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
        out.data = boxed;
        return out;
    }
    uint64_t scan_end = remaining - s->sep_len;
    for (uint64_t i = 0; i <= scan_end; i++) {
        if (memcmp(start + i, s->sep, s->sep_len) == 0) {
            z_t87_t* boxed = (z_t87_t*)z_xmalloc(sizeof(z_t87_t));
            boxed->data = start;
            boxed->size = i;
            s->cursor += i + s->sep_len;
            out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
            out.data = boxed;
            return out;
        }
    }
    /* no separator in remaining — final fragment */
    z_t87_t* boxed = (z_t87_t*)z_xmalloc(sizeof(z_t87_t));
    boxed->data = start;
    boxed->size = remaining;
    s->cursor = s->src_len;
    s->done = true;
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


static z_t5444_t z_t87_lines(const z_t87_t* self);
static z_t5444_t z_t87_lines(const z_t87_t* self) {
    z_t5444_t s;
    s.src = self->data;
    s.src_len = self->size;
    s.sep = NULL;
    s.sep_len = 0;
    s.cursor = 0;
    s.done = (self->size == 0);
    return s;
}


static z_t5373_t z_t5444_call(z_t5444_t* s);
static z_t5373_t z_t5444_call(z_t5444_t* s) {
    z_t5373_t out = {0};
    if (s->done) {
        out.tag = Z_OPTION_STRINGVIEW_TAG_NONE;
        return out;
    }
    const char* start = s->src + s->cursor;
    uint64_t remaining = s->src_len - s->cursor;
    uint64_t i = 0;
    while (i < remaining && start[i] != '\n') i++;
    uint64_t line_len = i;
    if (line_len > 0 && start[line_len - 1] == '\r') line_len--;
    z_t87_t* boxed = (z_t87_t*)z_xmalloc(sizeof(z_t87_t));
    boxed->data = start;
    boxed->size = line_len;
    if (i == remaining) {
        s->cursor = s->src_len;
        s->done = true;
    } else {
        s->cursor += i + 1;
        if (s->cursor >= s->src_len) s->done = true;
    }
    out.tag = Z_OPTION_STRINGVIEW_TAG_SOME;
    out.data = boxed;
    return out;
}


static bool z_t87_startsWith(const z_t87_t* self, const z_t87_t* prefix);
static bool z_t87_startsWith(const z_t87_t* self, const z_t87_t* prefix) {
    if (prefix->size > self->size) return false;
    if (prefix->size == 0) return true;
    return memcmp(self->data, prefix->data, prefix->size) == 0;
}

static bool z_t87_endsWith(const z_t87_t* self, const z_t87_t* suffix);
static bool z_t87_endsWith(const z_t87_t* self, const z_t87_t* suffix) {
    if (suffix->size > self->size) return false;
    if (suffix->size == 0) return true;
    return memcmp(self->data + (self->size - suffix->size),
                  suffix->data, suffix->size) == 0;
}

static uint64_t z_t87_indexOf_raw(const z_t87_t* self, const z_t87_t* needle);
static uint64_t z_t87_indexOf_raw(const z_t87_t* self, const z_t87_t* needle) {
    if (needle->size == 0) return 0;
    if (needle->size > self->size) return UINT64_MAX;
    uint64_t last = self->size - needle->size;
    for (uint64_t i = 0; i <= last; i++) {
        if (memcmp(self->data + i, needle->data, needle->size) == 0) {
            return i;
        }
    }
    return UINT64_MAX;
}


